//! Purpose:
//! Generated Rust tests for the committed PHP 8.5.10 `ext/fileinfo` PHPT corpus.
//!
//! Called from:
//! - `cargo test` through `tests/codegen/fileinfo_php_src.rs`.
//!
//! Key details:
//! - Generated by `scripts/gen_php_src_fileinfo_cases.py`; do not hand-edit.
//! - Each test carries its PHP source and assertion inline, and the test process
//!   never parses a `.phpt` file at run time.

use super::{assert_format, run_case};

/// Replays php-src `bug-gh11891.phpt`.
#[test]
fn test_php_src_fileinfo_bug_gh11891() {
    let out = run_case(r#"<?php
var_dump(
    (new \finfo(\FILEINFO_MIME_TYPE))->file(
        __DIR__ . '/bug-gh11891.svg',
    ),
);
"#, &[], &[]);
    assert_eq!(out, r#"string(13) "image/svg+xml""#);
}

/// Replays php-src `bug57547.phpt`.
#[test]
fn test_php_src_fileinfo_bug57547() {
    let out = run_case(r#"<?php

$filenames = array("..", __FILE__);

foreach ($filenames as $filename) {
    $finfo = new finfo(FILEINFO_MIME);
    var_dump($finfo->file($filename));

    $finfo2 = new finfo();
    var_dump($finfo2->file($filename, FILEINFO_MIME));
}

"#, &[], &[]);
    assert_eq!(out, r#"string(9) "directory"
string(9) "directory"
string(28) "text/x-php; charset=us-ascii"
string(28) "text/x-php; charset=us-ascii""#);
}

/// Replays php-src `bug61173.phpt`.
#[test]
fn test_php_src_fileinfo_bug61173() {
    let out = run_case(r#"<?php

try {
    $finfo = new finfo(1, '', false);
    var_dump($finfo);
} catch (TypeError $e) {
    echo $e->getMessage(), "\n";
}
"#, &[], &[]);
    assert_eq!(out, r#"finfo::__construct() expects at most 2 arguments, 3 given"#);
}

