/// Replays php-src `finfo_uninitialized.phpt`.
#[test]
fn test_php_src_fileinfo_finfo_uninitialized() {
    let out = run_case(r#"<?php

$finfo = (new ReflectionClass('finfo'))->newInstanceWithoutConstructor();

try {
	var_dump(finfo_set_flags($finfo, FILEINFO_NONE));
} catch (Error $e) {
	echo $e::class, ": ", $e->getMessage(), PHP_EOL;
}

try {
	var_dump($finfo->set_flags(FILEINFO_NONE));
} catch (Error $e) {
	echo $e::class, ": ", $e->getMessage(), PHP_EOL;
}

try {
	var_dump(finfo_file($finfo, __FILE__));
} catch (Error $e) {
	echo $e::class, ": ", $e->getMessage(), PHP_EOL;
}

try {
	var_dump($finfo->file(__FILE__));
} catch (Error $e) {
	echo $e::class, ": ", $e->getMessage(), PHP_EOL;
}

try {
	var_dump(finfo_buffer($finfo, file_get_contents(__FILE__)));
} catch (Error $e) {
	echo $e::class, ": ", $e->getMessage(), PHP_EOL;
}

try {
	var_dump($finfo->file(file_get_contents(__FILE__)));
} catch (Error $e) {
	echo $e::class, ": ", $e->getMessage(), PHP_EOL;
}

"#, &[], &[]);
    assert_eq!(out, r#"Error: Invalid finfo object
Error: Invalid finfo object
Error: Invalid finfo object
Error: Invalid finfo object
Error: Invalid finfo object
Error: Invalid finfo object"#);
}

/// Replays php-src `finfo_upstream.phpt`.
#[test]
fn test_php_src_fileinfo_finfo_upstream() {
    let out = run_case(r#"<?php

$lst = glob(__DIR__ . DIRECTORY_SEPARATOR . "upstream/*.testfile");

foreach($lst as $p) {
	$mp = dirname($p) . DIRECTORY_SEPARATOR . basename($p, ".testfile") . ".magic";
	$tp = dirname($p) . DIRECTORY_SEPARATOR . basename($p, ".testfile") . ".result";
	$finfo = finfo_open(FILEINFO_NONE, file_exists($mp) ? $mp : NULL);
	$i = finfo_file( $finfo, $p);
	$exp = trim(file_get_contents($tp));
	if ($i !== $exp) {
		echo "'$p' failed\nexp: '$exp'\ngot: '$i'\n";
	} 
}

echo "==DONE==";
"#, &[], &[(r#"TZ"#, r#"UTC"#)]);
    assert_eq!(out, r#"==DONE=="#);
}

